    deviceIds: List<String>,
    severity: String,
    minDaysOpen: Int,
    config: FalconConfigDto,
    limit: Int = 1000
): DeviceVulnerabilityQueryResult = queryVulnerabilitiesWithMetadata(
    deviceIds, severity, minDaysOpen, config, limit,
